window.MG_LAZY_DATA["data/lazy/resources/security-v26-014-0ad595f391fc39ab.json"]={sha256:"0ad595f391fc39ab3e8fad739a1adf5077c84c2f0f3922705449df344eb743f6",value:{"sources":[{"id":"v26-case-6b1876607e73c2c4","url":"https://www.rfc-editor.org/rfc/rfc9162.html","title":"RFC 9162: Certificate Transparency Version 2.0","titleEn":"RFC 9162: Certificate Transparency Version 2.0","publisher":"IETF","scope":"查證具名案例與原理背景。課內數值、故障資料與判準為原創教學假設；請勿當作廠商規格或操作程序。","scopeEn":"Establish named case and principle context. Numbers, fault data, and criteria are original teaching assumptions, not manufacturer specifications or operating procedures."}],"media":{"courses":[{"courseId":"security-v26-014","videos":[],"guides":[]}]},"related":{"courses":[{"courseId":"security-v26-014","related":[{"id":"security-v26-015","referenceUrls":["https://www.rfc-editor.org/rfc/rfc8555.html"],"title":"ACME：憑證續期與故障預算","titleEn":"ACME: certificate renewal and failure budgets","why":"用兩課的可觀察驗收條件比較模型邊界：160與192位元組只涵蓋明示欄位，篡改證明拒絕；未宣稱此教學樹就是現行瀏覽器CT政策。 交付兩棵樹的路徑計算、篡改負例與SCT/包含/一致性證據清單。","whyEn":"Compare model boundaries using observable acceptance criteria: The 160 and 192 bytes cover only stated fields, tampered proofs fail, and the teaching tree is not presented as current browser CT policy. Deliver path calculations for both trees, tampering negatives and separate SCT/inclusion/consistency evidence.","difference":"以自有測試域名的紙面訂單追蹤account、order、authorization、challenge與憑證；分開標示挑戰成功、簽發成功及服務實際載入。","differenceEn":"Trace account, order, authorization, challenge and certificate in a paper workflow for an owned test domain; separate challenge success, issuance and actual service loading.","transfer":"保留單位與邊界條件，僅轉移可證明相容的驗證方法。","transferEn":"Retain units and boundary conditions; transfer only demonstrably compatible verification methods.","practice":["對2的整數次方葉數，單葉包含路徑需要log2(N)個兄弟雜湊；證明驗證依順序組合，不能將所有雜湊任意排序。 N=32，每個雜湊32位元組，只計路徑雜湊，不含簽章、索引與樹頭。 log2(32)×32=160位元組；N=64時6×32=192位元組。","續期餘裕=到期日−開始續期日；可重試預算需另扣維護或故障時間，成功下載憑證不表示所有服務都已更新。 教學憑證在第30日到期，原定第20日開始續期；這些日期是示例而非公開CA有效期規則。 30−20=10日餘裕；若延至第25日開始則只剩5日。","比較兩個模型的輸入、誤差與驗收條件，記錄不能沿用的假設。"],"practiceEn":["For a power-of-two leaf count, a single-leaf path uses log2(N) sibling hashes; verification combines them in order, not arbitrary sorted order. N=32 and each hash is 32 bytes; count path hashes only, excluding signatures, indices and tree heads. log2(32)×32=160 bytes; N=64 needs 6×32=192 bytes.","Renewal margin is expiry day minus renewal-start day; maintenance and outages consume it, and a downloaded certificate does not prove every service updated. A teaching certificate expires on day 30 and renewal starts on day 20; these are invented dates, not public-CA validity rules. 30−20=10 days of margin; delaying start to day 25 leaves 5 days.","Compare inputs, errors, and criteria; document assumptions that cannot be transferred."]},{"id":"security-v26-024","referenceUrls":["https://bind9.readthedocs.io/en/latest/reference.html"],"title":"ISC BIND：遞迴權限、快取與分割視圖","titleEn":"ISC BIND: recursion permissions, caching and split views","why":"用兩課的可觀察驗收條件比較模型邊界：160與192位元組只涵蓋明示欄位，篡改證明拒絕；未宣稱此教學樹就是現行瀏覽器CT政策。 交付兩棵樹的路徑計算、篡改負例與SCT/包含/一致性證據清單。","whyEn":"Compare model boundaries using observable acceptance criteria: The 160 and 192 bytes cover only stated fields, tampered proofs fail, and the teaching tree is not presented as current browser CT policy. Deliver path calculations for both trees, tampering negatives and separate SCT/inclusion/consistency evidence.","difference":"用example.test建立內外視圖表；分開畫權威回答與遞迴查詢權限，拒絕未授權遞迴不應破壞必要公開權威回答。","differenceEn":"Build internal/external views for example.test; separate authoritative answers from recursion permissions so unauthorized recursion is denied without breaking required public authority.","transfer":"保留單位與邊界條件，僅轉移可證明相容的驗證方法。","transferEn":"Retain units and boundary conditions; transfer only demonstrably compatible verification methods.","practice":["對2的整數次方葉數，單葉包含路徑需要log2(N)個兄弟雜湊；證明驗證依順序組合，不能將所有雜湊任意排序。 N=32，每個雜湊32位元組，只計路徑雜湊，不含簽章、索引與樹頭。 log2(32)×32=160位元組；N=64時6×32=192位元組。","理想化上游查詢數=總遞迴需求×(1−快取命中率)；快取命中高不表示ACL正確，安全與負載須分開驗證。 合成需求每分鐘40000筆、命中率90%；忽略預取、重試與單次查詢衍生多筆上游交換。 40000×(1−0.90)=4000筆上游查詢；命中率95%時為2000筆。","比較兩個模型的輸入、誤差與驗收條件，記錄不能沿用的假設。"],"practiceEn":["For a power-of-two leaf count, a single-leaf path uses log2(N) sibling hashes; verification combines them in order, not arbitrary sorted order. N=32 and each hash is 32 bytes; count path hashes only, excluding signatures, indices and tree heads. log2(32)×32=160 bytes; N=64 needs 6×32=192 bytes.","Ideal upstream query count equals recursive demand×(1−cache hit rate); high cache efficiency does not prove correct ACLs. Synthetic demand is 40000 requests/minute with 90% cache hit rate; ignore prefetch, retries and multi-exchange resolution. 40000×(1−0.90)=4000 upstream queries; a 95% hit rate gives 2000.","Compare inputs, errors, and criteria; document assumptions that cannot be transferred."]}],"references":[{"id":"v26-case-f8688b0a88209a6e","url":"https://www.rfc-editor.org/rfc/rfc8555.html","title":"RFC 8555: Automatic Certificate Management Environment","titleEn":"RFC 8555: Automatic Certificate Management Environment","publisher":"IETF","scope":"查證具名案例與原理背景。課內數值、故障資料與判準為原創教學假設；請勿當作廠商規格或操作程序。","scopeEn":"Establish named case and principle context. Numbers, fault data, and criteria are original teaching assumptions, not manufacturer specifications or operating procedures."},{"id":"v26-case-236d191fe36a7161","url":"https://bind9.readthedocs.io/en/latest/reference.html","title":"BIND 9 Configuration Reference","titleEn":"BIND 9 Configuration Reference","publisher":"ISC","scope":"查證具名案例與原理背景。課內數值、故障資料與判準為原創教學假設；請勿當作廠商規格或操作程序。","scopeEn":"Establish named case and principle context. Numbers, fault data, and criteria are original teaching assumptions, not manufacturer specifications or operating procedures."}],"overview":"比較相鄰案例與另一組案例的模型、可量測結果及可轉移的驗證方法。","overviewEn":"Compare neighboring and cross-group cases by model, measurable outcome, and transferable verification method."}]},"places":{"courses":[]},"vendors":{"courses":[],"vendors":[]}}};
